INSERT INTO ai_feedback_reports VALUES(42,1,18,'weekly','本周总结（1月第1周）：新年首练状态极佳，标准俯卧撑突破10个。','2026-01-05T08:00:00',NULL,'2026-06-01 18:21:41');
INSERT INTO ai_feedback_reports VALUES(43,1,18,'monthly','6月月度总结：入会第一个月，从零基础到建立训练习惯。核心激活、呼吸模式初步掌握。体重-2kg。','2025-07-01T08:00:00',NULL,'2026-06-01 18:21:41');
INSERT INTO ai_feedback_reports VALUES(44,1,18,'monthly','9月月度总结：训练满3个月，累计减重4kg。背痛消失，圆肩改善。饮食从外卖转型为自带健康餐。','2025-10-01T08:00:00',NULL,'2026-06-01 18:21:41');
INSERT INTO ai_feedback_reports VALUES(45,1,18,'monthly','12月月度总结：入会半年，体重68kg降至61kg，累计减重7kg。骨盆趋于中立，核心力量达预期。','2026-01-01T08:00:00',NULL,'2026-06-01 18:21:41');
INSERT INTO ai_feedback_reports VALUES(46,1,18,'quarterly','第一季度总结（6-8月）：从评估到适应到突破。核心从零到平板支撑60秒。体重-4kg，背痛消失。','2025-09-01T08:00:00',NULL,'2026-06-01 18:21:41');
INSERT INTO ai_feedback_reports VALUES(47,1,18,'yearly',unistr('一周年年度总结（2025.6 - 2026.6）：\u000a\u000a这一年，你完成了从产后恢复到重获力量的蜕变。\u000a\u000a数字见证：体重68kg→61kg，累计减重7kg。52次训练，从核心激活到标准俯卧撑。8张体态照片记录下每一个变化。\u000a\u000a你已经不是一年前的自己了。骨盆前倾改善、圆肩消失、背痛不再。更重要的是，你建立起了可持续的健康生活习惯——自己做饭、规律训练、早睡早起。\u000a\u000a下一个目标：马甲线，我们一起去实现。'),'2026-06-01T08:00:00',NULL,'2026-06-01 18:21:41');
