INSERT INTO member_memories VALUES(1,1,18,'入会第一天，完成首次体态评估。骨盆前倾、圆肩、核心力量薄弱是三大重点区域。',NULL,'milestone',1,'2025-06-01 11:00:00');
INSERT INTO member_memories VALUES(2,1,18,'第一次团体课后主动询问普拉提器械使用方法，学习意愿很强。',NULL,'note',1,'2025-06-18 15:00:00');
INSERT INTO member_memories VALUES(3,1,18,'连续训练7天达成。平板支撑突破60秒，她自己也很惊喜。','{"streak":7}','milestone',1,'2025-07-13 17:00:00');
INSERT INTO member_memories VALUES(4,1,18,'偏爱普拉提器械课。喜欢练后喝拿铁。对音乐有要求，喜欢轻音乐。','{"favorite":"普拉提器械","drink":"拿铁","music":"轻音乐"}','preference',1,'2025-09-01 12:00:00');
INSERT INTO member_memories VALUES(5,1,18,'3个月AI总结：训练习惯已建立，饮食转型成功，体重-4kg。建议进入力量进阶。',NULL,'ai_summary',1,'2025-09-08 08:00:00');
INSERT INTO member_memories VALUES(6,1,18,'入会一周年。52次训练，从产后恢复到自信满满。她说这里像第二个家。','{"anniversary":true,"totalTrainings":52,"weightChange":-7}','milestone',1,'2026-06-01 10:00:00');
INSERT INTO member_memories VALUES(7,1,18,unistr('v2\u000a还行，慢慢找到节奏\u000a更灵活了,睡得更好了\u000a训练后第二天不会那么酸了，身体恢复变快\u000a想尝试普拉提器械课\u000a谢谢教练每次都很有耐心'),'{"FORM_VERSION":"v2","ADAPTATION_FEELING":"还行，慢慢找到节奏"}','self_report',NULL,'2026-06-03 10:07:28');
INSERT INTO member_memories VALUES(8,1,18,unistr('v2\u000a睡眠更稳定\u000a开始自己带午餐，蛋白质比以前多了\u000a平板支撑突破60秒\u000a每周坚持练4次'),'{"FORM_VERSION":"v2","MOST_NOTICEABLE_CHANGE_30D":"睡眠更稳定"}','milestone',NULL,'2026-06-03 10:07:28');
INSERT INTO member_memories VALUES(9,1,18,unistr('v2\u000a体态明显改善，朋友都说我站姿变好\u000a每周至少来3次，风雨无阻\u000a工作压力还是大，但训练成了缓冲\u000a不再焦虑体重，更关注身体感受\u000a训练已经从任务变成习惯，不去反而觉得少了点什么\u000a有几次加班到很晚，但还是赶来上了晚课\u000a核心力量再上一个台阶'),'{"FORM_VERSION":"v2","LIFE_STATUS":"工作压力还是大，但训练成了缓冲"}','milestone',NULL,'2026-06-03 10:07:28');
INSERT INTO member_memories VALUES(10,1,18,unistr('v2\u000a心态彻底变了，运动成了生活的一部分\u000a一整年没有中断超过两周\u000a夏天的时候第一次完整跟完一节课没休息\u000a这里不是健身房，是让你学会和自己相处的空间\u000a我不再去刻意坚持，因为坚持已经变成我是谁的一部分\u000a感谢小桥教练一年的陪伴，每次低谷都是她让我没有放弃\u000a谢谢你没有放弃，谢谢你愿意给自己一个机会\u000a希望明年能开始尝试器械进阶'),'{"FORM_VERSION":"v2"}','milestone',NULL,'2026-06-03 10:07:28');
